"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["1099"],{988(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>d,toc:()=>c,assets:()=>h});var s=JSON.parse('{"id":"m1-docker-networking/lesson-1-distributed-systems-cloud-native","title":"Lesson 1: Distributed Systems & the Cloud Native Landscape","description":"You already ship software in containers. Over the next eight sessions you will take one ordinary","source":"@site/docs/m1-docker-networking/lesson-1-distributed-systems-cloud-native.md","sourceDirName":"m1-docker-networking","slug":"/m1-docker-networking/lesson-1-distributed-systems-cloud-native","permalink":"/k8s-distributed-systems/docs/m1-docker-networking/lesson-1-distributed-systems-cloud-native","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson 1: Distributed Systems & the Cloud Native Landscape"},"sidebar":"courseSidebar","previous":{"title":"Environment","permalink":"/k8s-distributed-systems/docs/setup/environment"},"next":{"title":"Lesson 2: Docker Networking \u2014 How Containers Find Each Other","permalink":"/k8s-distributed-systems/docs/m1-docker-networking/lesson-2-docker-networking"}}'),a=t(4848),i=t(8453),o=t(7684);let r={sidebar_position:1,title:"Lesson 1: Distributed Systems & the Cloud Native Landscape"},d="Distributed Systems & the Cloud Native Landscape",h={},c=[{value:"Why this matters at work",id:"why-this-matters-at-work",level:2},{value:"From one process to many: what a distributed system is",id:"from-one-process-to-many-what-a-distributed-system-is",level:2},{value:"The cloud native landscape: containers and orchestration",id:"the-cloud-native-landscape-containers-and-orchestration",level:2},{value:"Portability: OCI images and the Kubernetes API",id:"portability-oci-images-and-the-kubernetes-api",level:2},{value:"Where this lands, and what comes next",id:"where-this-lands-and-what-comes-next",level:2}];function l(e){let n={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"distributed-systems--the-cloud-native-landscape",children:"Distributed Systems & the Cloud Native Landscape"})}),"\n",(0,a.jsx)(o.A,{src:"decks/m1-distributed-systems-cloud-native.html",title:"M1 \xb7 Distributed Systems & the Cloud Native Landscape"}),"\n",(0,a.jsxs)(n.p,{children:['You already ship software in containers. Over the next eight sessions you will take one ordinary\n3-tier application \u2014 a web frontend, an API backend, a database \u2014 and move it the whole way from\n"three containers I start by hand" to "a self-healing, scalable service running on Kubernetes." This\nfirst part is the map for that journey. Before you touch a single ',(0,a.jsx)(n.code,{children:"docker"})," command, you need a clear\nmental model of what actually changes when an application stops being one process and becomes several\nthat talk over a network. Everything else in the course \u2014 every Service, every Deployment, every\nNetworkPolicy \u2014 is an answer to a problem this part names."]}),"\n",(0,a.jsx)(n.h2,{id:"why-this-matters-at-work",children:"Why this matters at work"}),"\n",(0,a.jsxs)(n.p,{children:["Think about the last time a request failed in your system and the error pointed at the wrong place.\nThe frontend logged a timeout, but the real problem was the database three hops away. Or a QA colleague\nfiled a bug that only reproduces when two services are deployed on different hosts \u2014 never on their\nlaptop. That gap, between where a failure ",(0,a.jsx)(n.em,{children:"shows up"})," and where it ",(0,a.jsx)(n.em,{children:"originates"}),", is the defining tax of\na distributed system. If your team is moving a monolith to microservices, you are not just\nreorganizing code; you are signing up to pay that tax on every request, every test run, and every\ndeploy. The goal of this part is to make the tax visible and predictable, so the rest of the course\ncan teach you the tools that manage it."]}),"\n",(0,a.jsx)(n.h2,{id:"from-one-process-to-many-what-a-distributed-system-is",children:"From one process to many: what a distributed system is"}),"\n",(0,a.jsx)(n.admonition,{title:"Analogy",type:"info",children:(0,a.jsxs)(n.p,{children:["A single-process application is a ",(0,a.jsx)(n.strong,{children:"home kitchen"}),': the cook, the ingredients, and the stove are all\nin one room, and "passing the salt" is reaching across the counter. A distributed system is a\n',(0,a.jsx)(n.strong,{children:"restaurant with a separate kitchen, bar, and stockroom connected by waiters"}),'. Nothing is on the\nsame counter anymore. Every "pass the salt" is now a request that travels, can be delayed, can arrive\ntwice, or can find nobody home. The food is the same; the ',(0,a.jsx)(n.em,{children:"coordination"})," is the whole new job."]})}),"\n",(0,a.jsx)(n.p,{children:"A distributed system is a set of independent components that run on separate hosts (or separate\ncontainers) and coordinate only by passing messages over a network. The moment you split a monolith\ninto a frontend, a backend, and a database, you have crossed a line that changes three everyday\nactivities."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Debugging changes."})," In a monolith, a stack trace is the whole story: it points at the line that\nthrew and the calls that led there, all in one address space. Split the app and a single user action\nbecomes a chain of network calls across processes. When it fails, the frontend's error (\"upstream\ntimeout\") is a symptom whose cause lives in another process's logs, on another host, possibly at\nanother time. You now debug by ",(0,a.jsx)(n.em,{children:"correlating"})," \u2014 matching a request across several logs \u2014 instead of by\nreading one trace. That is why request IDs, structured logs, and later distributed tracing stop being\nnice-to-haves."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Testing changes."}),' A monolith test can call a function and assert on the return value. Once there is\na network in the middle, "the backend is slow," "the backend returned a 500," and "the backend is\nsimply gone" are three distinct outcomes your frontend must handle \u2014 and none of them happen when both\nrun in the same process on a developer\'s laptop. The interesting bugs now live in the ',(0,a.jsx)(n.em,{children:"seams between"}),"\nservices, not inside any one of them, which is exactly why integration and contract testing matter more\nhere than they did before."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Deployment changes."})," One process means one deploy: it is up or it is down. Several processes means\nthey get deployed independently and, for real stretches of time, at ",(0,a.jsx)(n.em,{children:"different versions"}),". A new backend\nmust not break the frontend that is still running the old contract. Coordinating who ships when, and\nkeeping the pieces compatible across a rollout, becomes an ongoing operational concern rather than a\none-time release step."]}),"\n",(0,a.jsx)(n.p,{children:"Underneath those three, the same three technical concerns keep surfacing. They are worth naming\ndirectly, because the rest of the course is organized around them."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"State \u2014 where the truth lives."})," In the home kitchen, there is one fridge and everyone trusts it.\nSplit the system up and you must decide who ",(0,a.jsx)(n.em,{children:"owns"})," each piece of truth and how the others get a\nconsistent view of it. A ",(0,a.jsx)(n.strong,{children:"stateless"})," component keeps nothing durable between requests \u2014 any copy can\nserve any request, because the answer does not depend on which copy you happened to reach. A\n",(0,a.jsx)(n.strong,{children:"stateful"}),' component owns data that must survive and stay consistent. In our sample app the database\nowns the durable state; the frontend and backend are deliberately stateless. Get this ownership wrong\nand the failure is concrete: if you let the backend cache user data in its own memory and then run\nthree copies of it, the same user gets three different answers depending on which copy the load\nbalancer picked. That "push state to the edges, keep the middle stateless" instinct is why, later, the\nfrontend and backend become easily-scaled Deployments while Postgres becomes a carefully-managed\nStatefulSet.']}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Scalability \u2014 handling more by adding copies."})," There are two ways to handle more load. ",(0,a.jsx)(n.em,{children:"Vertical"}),"\nscaling gives one instance a bigger machine \u2014 more CPU, more memory. It is simple, but it has a ceiling\n(the biggest machine you can buy) and a single point of failure (that one machine). ",(0,a.jsx)(n.em,{children:"Horizontal"}),"\nscaling adds more instances and spreads the load across them, with no hard ceiling and no single point\nof failure. Distributed systems are built to scale horizontally \u2014 but only the stateless tiers can.\nYou can run ten copies of the stateless backend behind one address and any of them can serve any\nrequest. You cannot naively run ten copies of Postgres the same way: they each own data, and ten\nindependent copies would diverge instantly. Statelessness is the ",(0,a.jsx)(n.em,{children:"precondition"})," for horizontal scaling,\nwhich is why the two concerns above are really one concern seen twice."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Failure handling \u2014 partial failure is the normal case."})," In one process, either everything runs or\nthe process crashes; there is no in-between. Across a network there is a third state that dominates real\nincidents: ",(0,a.jsx)(n.em,{children:"one part is down or slow while the rest keeps running."})," Consider a concrete failure mode\nyour team will hit: the backend gets slow, so the frontend's calls start timing out; the frontend\nretries, which adds ",(0,a.jsx)(n.em,{children:"more"}),' load to the already-struggling backend, which makes it slower still \u2014 a\nretry storm that turns a small hiccup into a full outage. A robust distributed system treats a missing\nor slow dependency as an expected condition, not a catastrophe. Our sample app is built to demonstrate\nexactly this: the frontend still renders a useful page and shows a clear "backend unavailable" banner\nwhen the backend is gone, and the backend still answers and reports ',(0,a.jsx)(n.code,{children:"db: unavailable"})," instead of\nreturning a 500 when Postgres is unreachable. ",(0,a.jsx)(n.strong,{children:"Graceful degradation is a design choice you make on\npurpose"}),", and you will see it in the code you run today."]}),"\n",(0,a.jsx)(n.mermaid,{value:'flowchart LR\n  user([User]) --\x3e fe["frontend<br/>(Node.js)<br/>stateless"]\n  fe --\x3e|HTTP /api/products| be["backend<br/>(Python)<br/>stateless"]\n  be --\x3e|SQL :5432| db[("db<br/>Postgres<br/>owns state")]\n  fe -. "backend down \u2192<br/>show banner, keep serving" .-> fe\n  be -. "db down \u2192<br/>report status, keep answering" .-> be'}),"\n",(0,a.jsx)(n.h2,{id:"the-cloud-native-landscape-containers-and-orchestration",children:"The cloud native landscape: containers and orchestration"}),"\n",(0,a.jsx)(n.admonition,{title:"Analogy",type:"info",children:(0,a.jsxs)(n.p,{children:["A ",(0,a.jsx)(n.strong,{children:"shipping container"})," did not make cargo smaller \u2014 it made every cargo ",(0,a.jsx)(n.em,{children:"the same shape"})," on the\noutside, so any crane, ship, or truck could handle it without knowing what was inside. An OCI image\ndoes the same for software: whatever language or dependencies are inside, the outside is a standard\npackage that any compliant runtime can run."]})}),"\n",(0,a.jsx)(n.p,{children:'"Cloud native" names a way of building systems that assumes this container-shaped world: applications\nare packaged as images, run as disposable instances, and are managed by software rather than by hand.\nTwo layers make it work, and being precise about which layer does which job matters, because the rest\nof the course lives on the seam between them.'}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Containers"})," solve ",(0,a.jsx)(n.em,{children:"packaging and isolation for one instance"})," on one host. Docker gives you a\nreproducible image and an isolated process with its own filesystem and network namespace. Docker\nwill start a container, stop it, and connect a handful of them on a single machine. That is where its\njob ends: one host, instances you start and wire yourself. Docker has no opinion about what happens\nwhen that host dies, or when you need forty copies across ten machines."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Orchestration"})," solves ",(0,a.jsx)(n.em,{children:"running many instances across many hosts, and keeping them running."}),"\nScheduling containers onto machines, restarting the ones that die, replacing whole hosts, spreading\ncopies for availability, wiring up service discovery and load balancing \u2014 that is Kubernetes' job,\nand it is why Sessions 3\u20138 exist. Docker gets our app connected on one machine; Kubernetes runs it as\na service that survives machines coming and going."]}),"\n"]}),"\n",(0,a.jsxs)(n.p,{children:["Hold that boundary precisely, because it is easy to blur: Docker packages and runs ",(0,a.jsx)(n.em,{children:"one"})," container;\nKubernetes decides ",(0,a.jsx)(n.em,{children:"where and how many"})," containers run and keeps that true over time. Sessions 1\u20132 live\nentirely on Docker's side of the seam. Sessions 3\u20138 live on Kubernetes' side."]}),"\n",(0,a.jsxs)(n.p,{children:["The broader ecosystem around these two layers is catalogued by the ",(0,a.jsx)(n.strong,{children:"Cloud Native Computing Foundation\n(CNCF)"})," \u2014 hundreds of projects for networking, storage, observability, security, and delivery. You do\nnot need to memorize the landscape; you need the map. Kubernetes sits at its center as the common\n",(0,a.jsx)(n.strong,{children:"control plane"}),", and the tools your team already uses plug into it around the edges: your ",(0,a.jsx)(n.strong,{children:"CI/CD"}),"\npipeline builds an image and hands Kubernetes a new desired state; a ",(0,a.jsx)(n.strong,{children:"service mesh"})," manages the\nservice-to-service traffic ",(0,a.jsx)(n.em,{children:"between"})," the things Kubernetes runs; your ",(0,a.jsx)(n.strong,{children:"observability"}),' stack (metrics,\nlogs, traces) watches what Kubernetes is running and tells you when the partial failures above are\nhappening. Each of these is a layer on top of, or beside, Kubernetes \u2014 not a replacement for it. When a\nnew tool shows up in a design review, the useful question is "which layer is this, and how does it plug\ninto the control plane?" \u2014 and this course gives you the control plane those tools attach to.']}),"\n",(0,a.jsx)(n.h2,{id:"portability-oci-images-and-the-kubernetes-api",children:"Portability: OCI images and the Kubernetes API"}),"\n",(0,a.jsx)(n.p,{children:'Two standards are the reason "build once, run anywhere" is real rather than a slogan, and they map\ncleanly onto the two layers above.'}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"The OCI image"})," is the portable ",(0,a.jsx)(n.em,{children:"unit of software"}),". When you ",(0,a.jsx)(n.code,{children:"docker build"})," in this course, you\nproduce an image in the Open Container Initiative format. Conceptually that image is a ",(0,a.jsx)(n.strong,{children:"manifest"})," \u2014 a\nsmall document that lists a set of read-only filesystem layers plus the configuration to run them\n(the command, environment, exposed ports) \u2014 and each layer is content-addressed by a digest, so the\nimage is exactly the same bytes wherever it lands. That is why containerd, CRI-O, Podman, and every\nKubernetes node's runtime all understand it: they read the same manifest and stack the same layers. The\nimage you build on your laptop in Session 1 is the byte-identical artifact Kubernetes pulls and runs in\nSession 3. Nothing is rebuilt or translated; that is the portability guarantee, and it is why we build\nthe images ",(0,a.jsx)(n.em,{children:"now"})," and reuse them untouched."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"The Kubernetes API"})," is the portable ",(0,a.jsx)(n.em,{children:"unit of intent"}),'. Instead of a script that says "do these steps\non this machine," you write a declarative object \u2014 "I want three copies of this image, reachable under\nthis name" \u2014 and hand it to the API. This is the crucial difference between imperative and declarative:\nan imperative script encodes ',(0,a.jsx)(n.em,{children:"how"}),", and it is tied to the exact machine, ordering, and starting state\nit was written against, so it breaks the moment any of those differ. A declarative object encodes\n",(0,a.jsx)(n.em,{children:"what you want to be true"}),", and any conformant cluster \u2014 on any cloud, or on your laptop under KIND \u2014\nreconciles reality toward that same desired state the same way. Migrate to a new cluster and your\nmanifests come with you unchanged, while a pile of setup scripts would have to be rewritten. You will\nstart writing these objects in Session 3; for now, hold onto the idea that the ",(0,a.jsx)(n.em,{children:"image"})," and the\n",(0,a.jsx)(n.em,{children:"desired-state object"})," are the two things that make your work portable."]}),"\n",(0,a.jsx)(n.h2,{id:"where-this-lands-and-what-comes-next",children:"Where this lands, and what comes next"}),"\n",(0,a.jsx)(n.p,{children:"You now have the map: a distributed system trades one process's simplicity for independent pieces that\nmust coordinate over a network, which reshapes how you debug, test, and deploy \u2014 and forces you to be\ndeliberate about state, scalability, and partial failure. The cloud native world answers this with two\nlayers, containers and orchestration, and two portability standards, the OCI image and the Kubernetes\nAPI. The rest of the course is spent turning that map into working infrastructure."}),"\n",(0,a.jsxs)(n.p,{children:["The very first thing that map demands is concrete and immediate: if the pieces coordinate over a\nnetwork, they first have to ",(0,a.jsx)(n.em,{children:"find and reach each other"}),". That is a networking problem, and on a single\nhost it is Docker's to solve. Part 2 picks up exactly there \u2014 how Docker gives a container a network,\nand how to make our three tiers discover each other by name \u2014 and the lab right after it puts it into\npractice."]})]})}function u(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},7684(e,n,t){t.d(n,{A:()=>i});var s=t(4848);t(6540);var a=t(6497);function i({src:e,title:n="Slides"}){let t=(0,a.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,s.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var s=t(6540);let a={},i=s.createContext(a);function o(e){let n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);